import * as React from "react";
import { cn } from "@/lib/utils";

export interface SliderProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "onChange" | "type" | "value"> {
  /** Optional label shown above the slider. */
  label?: React.ReactNode;
  value: number;
  onChange: (value: number) => void;
  /**
   * Optional formatter for the value display shown to the right of the label.
   * If `label` is present and `formatValue` is provided (or the value is a
   * finite number), the formatted value is rendered as a mono / tabular hint.
   */
  formatValue?: (value: number) => string;
}

/**
 * A thin, accent-themed range slider. Uses a native `<input type="range">`
 * with styling injected via Tailwind arbitrary variants for both the WebKit
 * and Firefox thumb pseudo-elements. The label + value-readout row above the
 * track follows the design-system "field label" pattern (small caps, mono).
 */
const Slider = React.forwardRef<HTMLInputElement, SliderProps>(
  ({ label, value, onChange, formatValue, className, min, max, step, id: idProp, ...props }, ref) => {
    const autoId = React.useId();
    const id = idProp ?? (label !== undefined ? autoId : undefined);
    const display = formatValue ? formatValue(value) : String(value);
    return (
      <div className={cn("flex flex-col gap-2.5", className)}>
        {label !== undefined && (
          <div className="flex items-baseline justify-between gap-2">
            <label
              htmlFor={id}
              className="text-xs text-[var(--color-text-muted-light)] dark:text-[var(--color-text-muted-dark)]"
            >
              {label}
            </label>
            {formatValue && (
              <span className="text-xs tabular-nums text-[var(--color-text-secondary-light)] dark:text-[var(--color-text-secondary-dark)]">
                {display}
              </span>
            )}
          </div>
        )}
        <input
          ref={ref}
          type="range"
          id={id}
          value={value}
          min={min}
          max={max}
          step={step}
          aria-valuetext={display}
          onChange={e => onChange(Number(e.target.value))}
          className={cn(
            "appearance-none w-full h-1.5 rounded-full cursor-pointer",
            // Track: neutral-700 in dark (NOT neutral-800, which equals
            // --color-surface-dark #27272a -- the track would vanish on a Card).
            "bg-[var(--color-warm-200)] dark:bg-[var(--color-neutral-700)]",
            "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-accent-500)] focus-visible:ring-offset-2",
            // WebKit thumb
            "[&::-webkit-slider-thumb]:appearance-none",
            "[&::-webkit-slider-thumb]:w-4 [&::-webkit-slider-thumb]:h-4",
            "[&::-webkit-slider-thumb]:rounded-full",
            "[&::-webkit-slider-thumb]:bg-[var(--color-accent-500)]",
            "[&::-webkit-slider-thumb]:shadow-md",
            "[&::-webkit-slider-thumb]:transition-transform",
            "hover:[&::-webkit-slider-thumb]:scale-110",
            "active:[&::-webkit-slider-thumb]:scale-95",
            // Firefox thumb
            "[&::-moz-range-thumb]:appearance-none",
            "[&::-moz-range-thumb]:w-4 [&::-moz-range-thumb]:h-4",
            "[&::-moz-range-thumb]:rounded-full",
            "[&::-moz-range-thumb]:bg-[var(--color-accent-500)]",
            "[&::-moz-range-thumb]:border-0",
            "[&::-moz-range-thumb]:shadow-md",
            "disabled:opacity-50 disabled:cursor-not-allowed",
          )}
          {...props}
        />
      </div>
    );
  },
);
Slider.displayName = "Slider";

export { Slider };
